const waitTab = (p, name) => p.waitForFunction((n) => document.querySelector('.dtab.on .tname')?.textContent === n, name); // ?.: a fresh page boots on Start with no tab (TODO 343)
const stop = () => { try { server.kill(); } catch { /* already gone */ } };
process.on('exit', stop);

async function waitForServer() {
  for (let i = 0; i < 50; i++) {
    try { if ((await fetch(URL_)).ok) return; } catch { /* not up yet */ }
    await new Promise((r) => setTimeout(r, 100));
  }
  throw new Error('serve.mjs did not start');
}

function chromePath() {
  if (process.env.CHROME) return process.env.CHROME;
  const local = '/opt/pw-browsers/chromium-1194/chrome-linux/chrome';
  return existsSync(local) && !process.env.CI ? local : undefined;
}

// TODO 309: older flows open vector PDFs as drawings; share the Editable click across their pages and reloads.
function acceptEditablePdf() {
  new MutationObserver(() => {
    if (!window.__pdfopenManual) document.querySelector('[data-testid=pdfopen-editable]')?.click();
  }).observe(document, { childList: true, subtree: true });
}

// Older feature flows use controls now spread across docker tabs. Navigate with the UI
// before an action; visibility assertions still inspect the current screen unchanged.
function panelControl(page, locator) {
  return new Proxy(locator, { get(target, key) {
    if (['locator', 'first', 'last', 'nth', 'filter', 'getByRole', 'getByText'].includes(key)) return (...args) => panelControl(page, target[key](...args));
    if (['click', 'fill', 'check', 'uncheck', 'selectOption', 'focus', 'press', 'waitFor'].includes(key)) return async (...args) => {
      if (key === 'waitFor' && ['hidden', 'detached', 'attached'].includes(args[0]?.state)) return target[key](...args);
      if (!(await target.count())) await target.first().waitFor({ state: 'attached', timeout: 1500 }).catch(async () => {     // the Objects tree is drawn only while its tab shows (TODO 325)
        const tab = page.locator('[data-tab=objects]');
        if (await tab.count() && await tab.getAttribute('aria-selected') !== 'true') await tab.click();
      });
      const { panel, pane } = await target.evaluate((el) => ({ panel: !!el.closest('aside.panel'), pane: el.closest('[data-docker]')?.dataset.docker }));
      if (panel && await page.locator('[data-testid=panel-show]').isVisible()) await page.locator('[data-testid=panel-show]').click();
      if (pane) {
        const tab = page.locator(`[data-tab=${pane}]`);
        if (await tab.getAttribute('aria-selected') !== 'true') await tab.click();
        const guide = await target.evaluate((el) => ({ toggle: el.matches('[data-testid=guides-panel] .section-toggle'), inTree: !!el.closest('.guide-node') }));
        if (guide.inTree) {
          if (await page.getByTestId('obj-layout').getAttribute('aria-expanded') === 'false') await page.getByTestId('obj-layout').click();
          if (guide.toggle && key === 'click') return page.getByTestId('obj-guides').click(...args);
          if (await page.getByTestId('obj-guides').getAttribute('aria-expanded') === 'false') await page.getByTestId('obj-guides').click();
        }
        const sections = await target.evaluate((el) => {
          const keys = [];
          for (let p = el.parentElement; p; p = p.parentElement) if (p.classList.contains('docker-folded') && !p.querySelector('.section-toggle')?.contains(el)) keys.unshift(p.dataset.section);
          return keys;
        });
        for (const section of sections) await page.locator(`[data-section="${section}"] .section-toggle`).first().click();
      }
      return target[key](...args);
    };
    const value = target[key];
    return typeof value === 'function' ? value.bind(target) : value;
  } });
}

const base = { sheetW: 1000, sheetH: 700, gripTop: 0, gripRight: 0, gripBottom: 30, gripLeft: 0, partW: 120, partH: 80, gapX: 5, gapY: 5, rotate: '0', align: 'centre' };
const N0 = stepRepeat(base).count;                // the 30 mm bottom-gripper fixture, 120 × 80 parts: 8 × 7 = 56
let failed = 0;
const timings = {};
let afterStep = async () => {};
const steps = [];
function step(name, fn, { needs = [] } = {}) {
  steps.push({ name, fn, needs, afterStep });
}
async function runStep(page, { name, fn, afterStep }, shotDir) {
  const started = performance.now();
  try {
    await fn();
    await page.keyboard.press('Escape');
    await page.keyboard.press('Escape');
    assert.doesNotMatch(await page.getByTestId('cmd-prompt').textContent(), RUNNING_PROMPT, `${name} left a command running`);
    console.log('ok', name);
  } catch (e) {
    failed++;
    console.log('FAIL', name, '\n  ', e.message, '\n  at', ((e.stack || '').split('\n').find((l) => l.includes('browser.test.mjs')) || '').trim());
    try { console.log('  prompt:', await page.getByTestId('cmd-prompt').textContent()); }
    catch (err) { console.log('  prompt: unavailable:', err.message); }
    if (process.argv.includes('--shots')) {
      const safeName = name.replace(/[^a-zA-Z0-9_-]+/g, '-').slice(0, 120);
      try { await page.screenshot({ path: join(shotDir, `FAIL-${safeName}.png`) }); }
      catch (err) { console.log('  failure screenshot:', err.message); }
    }
    try { await afterStep(); } catch { /* best effort */ }
  }
  finally { timings[name] = Math.round((performance.now() - started) / 10) / 100; }
}

