        await p.mouse.down(); await p.mouse.move(gr.x + 30, gr.y + 20, { steps: 4 });
        assert.equal(await fillOf('[data-testid=grip-hot]'), 'rgb(165, 0, 0)');
        await p.keyboard.press('Escape'); await p.mouse.up();
