      assert.deepEqual(writes.map((w) => circles(readDxf(w.text))), [[5], [5, 7], [8, 9]], 'each Save writes just that sheet');
      await p.evaluate(() => { delete window.__TAURI__.dialog; delete window.__TAURI__.fs; });
