      assert.deepEqual(await fields(['10', '10', '10', '10']), ['10', '10', '10', '10'], tab + ': Standard check print is 10 mm');
      const std = await scale(), shot = await q('pdf-preview').evaluate((c) => c.toDataURL());
      await q('pdf-margin-office').click();
