      await page.getByTestId('canvas').getByRole('button', { name: 'Fit', exact: true }).click(); await settle();
      const b = await drawing.boundingBox(), label = `${['Solid', 'Dashed', 'Dotted'][style]} contour, part turned ${rot}°`;
