    await page.mouse.up();
    await t('draw-tip').waitFor({ state: 'hidden' });
    assert.equal(fieldOf((await savedDoc()).entities[0], 40), h0, 'cancelled: the height is as it was');
    const hb2 = await handleBox(1), x1 = hb2.x + hb2.width / 2, y1 = hb2.y + hb2.height / 2;
