    assert.ok(close(await lineOf(2), [20, 30, 140, 30]) && close(await lineOf(3), [20, 60, 140, 60]), 'the copies are moved');
    await undo(); await frames();
    assert.equal((await savedDoc()).entities.length, 2, 'one Ctrl+Z takes the copies back');
