    const lined = async () => { const s = await shape(); assert.ok(Math.abs(cross(s.vo, s.vi)) < 0.03 && s.vo[0] * s.vi[0] + s.vo[1] * s.vi[1] < 0, 'handles collinear, opposite ways: ' + JSON.stringify(s)); return s; };
