    let doc = await savedDoc(), e = doc.entities[3];
    assert.equal(e.type, 'LINE'); assert.equal(layerOf(e), 'Cut');
    assert.deepEqual([10, 20, 11, 21].map((c) => fieldOf(e, c)), [20, 45, 120, 45]);
    // a circle: inside, the radius shrinks by the distance
