    assert.deepEqual((await savedDoc()).entities.map((e) => e.type), ['LINE', 'LINE']);
    await page.keyboard.press('Control+z'); assert.deepEqual((await savedDoc()).entities.map((e) => e.type), ['INSERT', 'LINE']);
