      await page.keyboard.press('Control+a'); await typeCmd(cmd);
      assert.equal(await prompt(), `${label}: 2 outlines → ${count} outline${count === 1 ? '' : 's'}, area ${area} mm². Ctrl+Z puts the originals back`);
      assert.equal(await entCount(), count);
