      Object.assign(raw, addDimension(raw, buildDim(kind, { ...params, textH: 5 }, 1, radial ? 'PD_DIM_R1' : axis ? `PD_DIM_${axis.toUpperCase()}1` : 'PD_DIM_1', 2)));
