    assert.equal(await t('obj-search').inputValue(), 'ENGR');
    await t('obj-search').press('Escape');
    assert.equal(await t('obj-search').inputValue(), '');
    assert.deepEqual(await oLayers(), ['Cut', 'Engrave', '0']);
    await t('ptab-drawing').click();
