        assert.deepEqual(lineEnds97c((await probe()).raw), [[100, 100, 180, 100], [100, 180, 140, 220], [100, 300, 160, 340]]);
        assert.deepEqual((await probe()).labels.slice(original.labels.length), [kind === 'layout' ? 'Align left 3 parts' : 'Align left']);
